def set_rubric(q,elements,objective=False):
    keys=['operation','reasoning'] if objective else ['understanding','reasoning','validation']
    anchors=[elements[0],'依指定條件解釋機制、混淆與適用限制'] if objective else elements
    q['rubric']={'version':1,'total_points':12,'requires_human_review':True,'criteria':[{'id':key,'name':['結果與概念','理由與機制','限制與驗證'][i],'points':12/len(keys),'max_level':3,'levels':{'0':'未展現或相矛盾：'+anchor,'1':'只有名詞或有關鍵錯誤：'+anchor,'2':'核心正確但有小幅遺漏：'+anchor,'3':'完整且連結題目條件：'+anchor}} for i,(key,anchor) in enumerate(zip(keys,anchors))]}

def update_guide(q,solution):
    guide=q['answer']['teaching_guide'];guide['reference_answer']=solution
    guide['steps']=['辨認程式或案例的目標與已知條件。','追蹤資料流、狀態或評測條件，定位關鍵問題。','說明原因、替代做法與驗證方式；不需要手算數值。']
    guide['common_errors']=['只改名稱或套關鍵詞，沒有追蹤實際行為。','把單一機制或指標當成所有任務的品質保證。']
    guide['practical_transfer']='在小型資料上追蹤程式行為，先確認資料來源、邊界與評測条件，再建立基準與驗證案例。'
    q['answer']['expected_elements']=[solution,'用題目條件支持解釋','指出成立條件或合理驗證方式']

def mlm_guide(q):
    guide=q['answer']['teaching_guide']
    guide['reference_answer']='應改成 label = original[mask_index]。原程式 masked[mask_index] 已被換成 [MASK]，拿它作標籤會要求模型預測特殊標記本身，沒有恢復被移除內容。original 保留損壞前的 token，因此不必知道該 token 的具體字串即可找到正確資料來源。MLM 用可見的雙向上下文預測選定位置原 token；causal next-token 則以左側前綴預測下一位置，標籤對齊與可見範圍不同。'
    guide['steps']=['追蹤 original 與 masked 是兩份資料副本。','找到 masked[mask_index] 的覆寫位置，再檢查 label 的來源。','從 original[mask_index] 取得目標；比較 MLM 與 next-token 的位置和可見範圍。']

def revise(q):
    q=copy.deepcopy(q);qid=q['question_id'];number=int(qid.split('-')[-1]);extra=qid.startswith('ZJU-EX-')
    english=extra or number in ENGLISH_BASE
    changed=english or number in LOGIC_REVISIONS or number in (15,34,35,40,41)
    if not changed:return None
    q['payload']['language']='en' if english else 'zh-TW'
    if extra:
        if number<=12:
            title,prompt,option_labels=ENGLISH_CHOICES[number-1]
            # Map through canonical Chinese option text, not assumed option positions.
            from extra_bank import CHOICES
            original_labels={label:i for i,(_,label,_) in enumerate(CHOICES[number-1][4])}
            q['payload']['options']=[{'id':option['id'],'label':option_labels[original_labels[option['label']]]} for option in q['payload']['options']]
            q['title']=title;q['prompt']=prompt+(' Select all that apply. The operation score requires the exact set.' if q['payload']['multiple'] else ' Select one answer.')+' Explain your reasoning.'
        else:
            title,prompt,expected=ENGLISH_INTERACTIVE[number-13];q['title']=title;q['prompt']=prompt
            key=q['answer']['objective']['type']
            q['answer']['objective']['expected']=expected
            if key=='order':q['payload']['cards']=expected
            elif key=='mapping':q['payload'].update(left=list(expected),right=list(expected.values())[::-1])
            q['answer']['teaching_guide']['reference_answer']='核准的英文操作結果：'+encode(expected)+'\n'+q['answer']['teaching_guide']['reference_answer']
    elif number in ENGLISH_BASE:
        q['title'],q['prompt']=ENGLISH_BASE[number]
        if number in (19,25,33):
            expected={19:{'BERT':'encoder-only','T5':'encoder-decoder','GPT':'decoder-only'},25:{'Q':'decoder','K':'encoder','V':'encoder'},33:{'Mamba':'input_dependent_selection','TTT':'test_time_learning'}}[number]
            q['answer']['objective']={'type':'mapping','expected':expected}
            if number==25:q['payload']['labels']={'decoder':'Decoder hidden states','encoder':'Encoder outputs'}
            if number==33:q['payload']['labels']={'input_dependent_selection':'Input-dependent state selection','test_time_learning':'Test-time learning updates internal memory'}
    if not extra and number in LOGIC_REVISIONS:
        kind,title,prompt,code,options,correct,solution=LOGIC_REVISIONS[number]
        q.update(kind=kind,title=title,prompt=prompt,tests={})
        q['payload']={'language':'zh-TW','reading_code':code};q['answer'].pop('objective',None)
        if options:
            q['payload'].update(options=[{'id':key,'label':text} for key,text in options],multiple=False)
            q['answer']['objective']={'type':'choice','expected':correct}
        update_guide(q,solution);q['answer']['teaching_guide']['reference_code']=None
        set_rubric(q,q['answer']['expected_elements'],objective=bool(options))
    if not extra and number==15:
        q.update(title='實作：逐筆比較評測答案',prompt='實作 compare_predictions(predictions, targets)，回傳逐筆是否相同的布林串列。兩個串列長度不同時拋 ValueError，空資料回傳 []，不得修改輸入。說明這個比較只能評估指定答案一致性，為何不能代表所有回答品質。',kind='python')
        q['payload']={'language':'zh-TW'}
        q['tests']={'function':'compare_predictions','mutation_check':True,'public':[{'args':[['yes','no'],['yes','yes']],'expected':[True,False]}],'hidden':[{'args':[[],[]],'expected':[]},{'args':[['a'],[]],'raises':'ValueError'},{'args':[['A','A','B'],['A','B','B']],'expected':[True,False,True]}]}
        update_guide(q,'先檢查長度是否一致，再以 zip 比較對應答案，回傳布林串列，不修改輸入。空串列自然回傳 []。這只量測提供的答案一致性；自由文字的等價說法、事实正確性與品質可能需要不同規準，不能把字串一致性当成所有任務的完整評估。')
        q['answer']['teaching_guide']['reference_code']='def compare_predictions(predictions, targets):\n    if len(predictions) != len(targets):\n        raise ValueError("length mismatch")\n    return [predicted == target for predicted, target in zip(predictions, targets)]\n'
        set_rubric(q,['公開與隱藏測試完整通過','保留輸入且處理空資料與長度錯誤','說明答案一致性指標的適用限制'])
    if not extra and number in (34,35,40,41):
        replacements={34:('Chinchilla 案例：固定算力的下一步','教材 2.1.1 的 Chinchilla 案例討論模型與訓練資料配置。針對模型很大但訓練資料不足的情境，提出固定算力下的下一步改善。說明觀察、原因假設、配置方案、控制條件、基準及失敗判準。不需計算 tokens／parameter。','先核對模型與資料是否配置失衡，區分訓練 tokens 與測試資料；不能只用參數量排名。'),35:('教材搜尋樹：比較策略的邏輯','教材 1.4 搜尋樹中，greedy 路徑機率低於另一完整候選。直接使用這個已知結果，不需計算倍數。解釋局部選擇如何錯失完整路徑；為開放故事生成提出改善、代價、基準、控制與品質驗證。','greedy 僅選局部最佳，完整路徑仍可能較差；序列機率不直接等於故事品質。'),40:('BERT Table 5：讀懂對照關係','原論文 Table 5：BERT_BASE 88.5、No NSP 87.9、LTR & No NSP 77.8、LTR & No NSP + BiLSTM 84.9，指標為 SQuAD dev F1。不需計算差值。判斷加 BiLSTM 的結果是否超越 BERT_BASE，指出哪些比較改變了不只一個因素，提出可執行的對照、機制與失敗判準。','84.9 未超過 88.5；BERT_BASE 與 LTR & No NSP 同時涉及方向／目標及 NSP 差異，不能把所有下降歸因 NSP。'),41:('Chinchilla 原論文：評測改善的解釋','原論文 §4.2.1 報告 Chinchilla 的 WikiText-103 PPL 低於 Gopher，並提醒較多訓練資料可能影響 train/test leakage；§4.1 也列出優化器及 tokenizer 差異。不需算相對下降。解釋能否把改善全歸因模型／資料比例，並提出去污染、控制條件、基準與失敗判準。','PPL 較低是觀察結果，不能單憑兩個模型把原因鎖定比例；資料污染、tokenizer 與優化器均需核對。')}
        title,prompt,first=replacements[number];q['title']=title;q['prompt']=prompt
        guide=q['answer']['teaching_guide'];steps=list(guide['steps']);steps[0]=first
        guide.update(steps=steps,reference_answer='\n'.join(steps));q['answer']['expected_elements'][0]=first
        q['rubric']['criteria'][0]['levels']={str(i):['未展現或與案例相矛盾','觸及觀察但有關鍵錯誤','核心案例條件正確但小幅遺漏','完整辨認觀察、比較條件與解釋界線'][i]+'：'+first for i in range(4)}
    if qid in CODES:q['payload']['reading_code']=CODES[qid]
    if q['payload'].get('reading_code'):
        q['payload']['code_reading']=True
        if english:q['answer']['teaching_guide']['reference_answer']='程式閱讀要核對資料來源、輸入／標籤或狀態相依；以題目指定條件為準。\n'+q['answer']['teaching_guide']['reference_answer']
    if qid=='ZJU-022':mlm_guide(q)
    if english:q['prompt']+=' You may explain your reasoning in English or Chinese.'
    q['analysis_metadata'].update(language=q['payload']['language'],content_revision=REVISION,assessment_focus='logic_and_concepts',code_reading=bool(q['payload'].get('reading_code')),grading_language_policy='Assess concepts, not English fluency; accept Chinese or English explanations.')
    q['analysis_metadata']['required_evidence']=q['answer']['expected_elements']
    return q

def apply(connection):
    count=0
    for row in latest_questions(connection):
        original=question(row,True)
        if original['question_id']=='ZJU-022' and original['version']==2 and original['review_status']=='draft' and original['analysis_metadata'].get('content_revision')==REVISION and '原 token「閱讀」' in original['answer']['teaching_guide']['reference_answer'] and not connection.execute('SELECT 1 FROM assignment_items WHERE question_version_id=?',(original['id'],)).fetchone():
            mlm_guide(original)
            connection.execute('UPDATE question_versions SET answer_json=? WHERE id=?',(encode(original['answer']),original['id']))
            audit(connection,None,'question_draft_guide_corrected',original['id'])
        if not original['question_id'].startswith('ZJU-') or original['analysis_metadata'].get('content_revision')==REVISION:continue
        # Only revise original authored versions; preserve later user edits for human review.
        if original['version']!=1:continue
        revised=revise(original)
        if revised:
            add_version(connection,revised,None,original['question_id']);count+=1
    return count

if __name__=='__main__':
    initialize()
    with db() as connection:print({'new_draft_versions':apply(connection)})
